const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arrachartPoint = ee.Geometry.Point(49.283, -13.683); // Arrachart Airport, Madagascar (Lon, Lat)
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';
  const rainfallThresholdInches = 22; // Question threshold

  // 2. Data Acquisition & Check
  const chirpsCollection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(arrachartPoint);

  const collectionSize = await chirpsCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log(`No CHIRPS images found for January 2020 at Arrachart.`);
    console.log("C1");
    return;
  }

  // Calculate total rainfall for the month
  // CHIRPS data is in mm/day, so sum all daily images.
  const totalRainfallImage = chirpsCollection.sum();

  // 3. Processing & 4. Calculation
  // Use a reasonable scale for point data to ensure calculation.
  const scale = 5000; // CHIRPS original resolution is ~5.5km, so 5000m is fine.
  const regionReducer = totalRainfallImage.reduceRegion({
    reducer: ee.Reducer.sum(), // 'sum' is appropriate here as we want the value at the point.
    geometry: arrachartPoint,
    scale: scale,
    maxPixels: 1e9
  });

  let totalRainfallMm = await ee.Number(regionReducer.get('precipitation')).getInfo();

  // Validate calculation result
  if (totalRainfallMm === null || isNaN(totalRainfallMm)) {
    console.log("Calculation failed: Could not retrieve total rainfall or result is invalid.");
    console.log("C3");
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const totalRainfallInches = totalRainfallMm / 25.4;

  // Print intermediate stats
  console.log(`CHIRPS Images in collection: ${collectionSize}`);
  console.log(`Total rainfall for January 2020 at Arrachart: ${totalRainfallMm.toFixed(2)} mm`);
  console.log(`Total rainfall for January 2020 at Arrachart: ${totalRainfallInches.toFixed(2)} inches`);
  console.log(`Threshold: ${rainfallThresholdInches} inches`);

  // 5. Validation & Final Answer
  if (totalRainfallInches > rainfallThresholdInches) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
